function [summary,errors]=run_q5_procedure_cohort_specification(subject_numbers)
% Q5 Procedure specification: four-cell factorial model, no estimation.
if nargin<1,subject_numbers=1;end;subject_numbers=subject_numbers(:)';assert(all(ismember(subject_numbers,1:30)));
repo_root=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');v2=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1');raw=fullfile(fl,'nirs_spm_inputs');ef=fullfile(glm,'amended_snirf','event_tables_full_annotations','event_table_all_subjects_full_annotations.csv');root=fullfile(repo_root,'results','q5_intrinsic_procedure','cohort_specification');if ~isfolder(root),mkdir(root);end
addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));E=readtable(ef,'TextType','string');E.condition=string(E.condition);E.subject_num=double(E.subject_id);summary=table();errors=table();manifest=table();
for sn=subject_numbers
 sid=sprintf('subject%03d',sn);sr=fullfile(root,sid);if ~isfolder(sr),mkdir(sr);end
 try
  if ismember(sn,[1 2 10]),d=fullfile(v2,sid);nf=fullfile(d,sprintf('%s_nirs_data.mat',sid));ev=readtable(fullfile(d,sprintf('%s_events_used_v2.csv',sid)),'TextType','string');policy="first_complete_cycle";else,d=fullfile(raw,sid);nf=fullfile(d,sprintf('%s_nirs_data.mat',sid));ev=E(E.subject_num==sn,:);policy="full_recording";end;assert(isfile(nf),'Missing NIRS input.');ev.condition=string(ev.condition);
  src=["LILEProcedure","HILEProcedure","LIHEProcedure","HIHEProcedure"];sel=sortrows(ev(ismember(ev.condition,src),:),'onset_sec');assert(all(ismember(src,unique(sel.condition))),'%s is missing a Q5 Procedure cell.',sid);on=cell(1,4);du=cell(1,4);for i=1:4,ix=sel.condition==src(i);assert(sum(ix)==1,'%s must have exactly one %s.',sid,src(i));on{i}=double(sel.onset_sec(ix))';du{i}=double(sel.duration_sec(ix))';end
  names=cellstr(src);writetable(sel,fullfile(sr,sprintf('%s_q5_procedure_events_used.csv',sid)));save(fullfile(sr,sprintf('%s_q5_procedure_multiple_conditions.mat',sid)),'names','on','du','-v7');manifest=[manifest;table(string(sid),sn,policy,string(nf),'VariableNames',{'subject_id','subject_num','selection_policy','nirs_data_file'})]; %#ok<AGROW>
  for h=["hbo","hbr"],if h=="hbo",hb="HbO";else,hb="HbR";end;hr=fullfile(sr,char(hb));if ~isfolder(hr),mkdir(hr);end;S=specification_batch(nf,char(h),'DCT, 128','none',0,hr,0,0,1,names,on,du);X=full(S.xX.X);rn=string(S.xX.name(:));ic=contains(lower(rn),'constant');assert(size(X,2)==5&&sum(ic)==1,'Expected four Q5 task columns and constant.');tx=X(:,~ic);Z=(tx-mean(tx))./std(tx,0,1);R=corrcoef(Z);mr=max(abs(R(~eye(4))));v=zeros(4,1);for j=1:4,y=tx(:,j);z=[ones(size(X,1),1),tx(:,setdiff(1:4,j))];r2=1-sum((y-z*(z\y)).^2)/sum((y-mean(y)).^2);v(j)=1/max(1-r2,eps);end;rk=rank(X);pass=rk==5&&mr<.95&&max(v)<=10;writematrix(X,fullfile(hr,sprintf('%s_%s_q5_procedure_convolved_design.csv',sid,hb)));writetable(table((1:numel(rn))',rn,ic,'VariableNames',{'column_index','regressor','is_constant'}),fullfile(hr,sprintf('%s_%s_q5_procedure_regressor_table.csv',sid,hb)));writetable(table(rn(~ic),v,'VariableNames',{'regressor','vif'}),fullfile(hr,sprintf('%s_%s_q5_procedure_vif.csv',sid,hb)));summary=[summary;table(string(sid),hb,size(X,1),5,rk,cond(Z),mr,max(v),pass,'VariableNames',{'subject_id','hemoglobin','n_scans','n_columns','rank','normalized_condition_number','max_abs_correlation','max_vif','qa_pass'})];fprintf('%s %s: rank %d/5, max |r| %.3f, max VIF %.3f, pass=%d\n',sid,hb,rk,mr,max(v),pass);end
 catch ME,errors=[errors;table(string(sid),sn,string(ME.identifier),string(ME.message),'VariableNames',{'subject_id','subject_num','error_identifier','error_message'})]; %#ok<AGROW>;fprintf(2,'ERROR %s: %s\n',sid,ME.message);end
end
tag=sprintf('%03d_to_%03d',min(subject_numbers),max(subject_numbers));writetable(manifest,fullfile(root,sprintf('q5_procedure_manifest_%s.csv',tag)));writetable(summary,fullfile(root,sprintf('q5_procedure_design_qa_%s.csv',tag)));writetable(errors,fullfile(root,sprintf('q5_procedure_specification_errors_%s.csv',tag)));assert(isempty(errors),'Q5 Procedure specification failed.');assert(all(summary.qa_pass),'Q5 Procedure design QA failed.');
end
